settings.custom_css:
selector .ao-header { display:flex; align-items:center; justify-content:space-between; min-height:80px; width:100%; }
selector .ao-header-logo { display:flex; align-items:center; gap:14px; flex-shrink:0; text-decoration:none; }
selector .ao-header-logo-icon { width:34px; height:34px; background-image:url(https://abhayoyun.org/wp-content/uploads/icon1.png); background-size:contain; background-repeat:no-repeat; background-position:center; flex-shrink:0; filter:brightness(0) saturate(100%) invert(69%) sepia(54%) saturate(550%) hue-rotate(4deg) brightness(94%); }
selector .ao-header-logo-text { font-family:'Playfair Display',serif; font-size:20px; font-weight:700; letter-spacing:0.06em; background:linear-gradient(135deg,#d4a853,#f9d58b,#b8893a); -webkit-background-clip:text; -webkit-text-fill-color:transparent; background-clip:text; line-height:1; }
selector .ao-header-logo-sub { font-family:'Inter',sans-serif; font-size:8.5px; font-weight:600; letter-spacing:0.28em; text-transform:uppercase; color:rgba(212,168,83,0.65); margin-top:4px; }
selector .ao-header-nav { display:flex; align-items:center; gap:32px; }
selector .ao-header-nav a { font-family:'Inter',sans-serif; font-size:11px; font-weight:600; letter-spacing:0.18em; text-transform:uppercase; color:rgba(255,255,255,0.75); text-decoration:none; transition:color .2s; }
selector .ao-header-nav a:hover { color:#d4a853; }
selector .ao-header-right { display:flex; align-items:center; gap:8px; flex-shrink:0; }
selector .ao-header-social { display:flex; align-items:center; gap:6px; border-right:1px solid rgba(255,255,255,0.12); padding-right:16px; margin-right:8px; }
selector .ao-header-social a { display:inline-flex; align-items:center; justify-content:center; width:30px; height:30px; color:rgba(255,255,255,0.45); border-radius:50%; transition:color .2s, background .2s; }
selector .ao-header-social a:hover { color:#d4a853; background:rgba(212,168,83,0.08); }
selector .ao-header-cta { display:inline-flex; align-items:center; padding:10px 24px; background:linear-gradient(135deg,#d4a853,#f9d58b); color:#050810; font-family:'Inter',sans-serif; font-size:10px; font-weight:700; letter-spacing:0.18em; text-transform:uppercase; border-radius:4px; text-decoration:none; white-space:nowrap; box-shadow:0 6px 16px rgba(212,168,83,0.35); transition:box-shadow .3s, transform .2s; }
selector .ao-header-cta:hover { box-shadow:0 10px 28px rgba(212,168,83,0.55); transform:translateY(-1px); }
@media (max-width:767px) {
  selector .ao-header { min-height:60px; }
  selector .ao-header-nav { display:none !important; }
  selector .ao-header-social { display:none !important; }
  selector .ao-header-logo-text { font-size:16px; }
  selector .ao-header-logo-sub { font-size:7px; }
  selector .ao-header-logo-icon { width:28px; height:28px; }
  selector .ao-header-cta { padding:8px 16px; font-size:8px; letter-spacing:0.12em; }
}
@media (min-width:768px) and (max-width:1024px) {
  selector .ao-header-nav { gap:20px; }
  selector .ao-header-nav a { font-size:10px; }
  selector .ao-header-social { display:none !important; }
  selector .ao-header-cta { padding:8px 18px; font-size:9px; }
}
.sticky-header { position: sticky !important; top: 0; z-index: 100; }
